from fractions import Fraction as F
from collections import defaultdict

# All segments in the submitted SVG, including redundant/overlapping strokes.
raw = [
    ("0", "16.81045", "0", "14.80251"),
    ("0", "0", "0", "14.80251"),
    ("0", "21.72644", "0", "16.81045"),
    ("-15.59808", "14.80251", "-15.59808", "21.72644"),
    ("-9.98277", "8.80251", "0", "8.80251"),
    ("9.07607", "21.72644", "9.07607", "14.80251"),
    ("5.35488", "14.80251", "0", "14.80251"),
    ("0", "21.72644", "9.07607", "21.72644"),
    ("0", "14.80251", "-15.59808", "14.80251"),
    ("-5.19615", "11.80251", "0", "14.80251"),
    ("0", "8.80251", "-5.19615", "11.80251"),
    ("-15.59808", "21.72644", "0", "21.72644"),
    ("9.07607", "14.80251", "9.07607", "9.32558"),
    ("-15.59808", "8.80251", "-9.98277", "8.80251"),
    ("9.07607", "9.32558", "9.07607", "0"),
    ("0", "14.80251", "0", "21.72644"),
    ("9.07607", "14.80251", "5.35488", "14.80251"),
    ("-15.59808", "14.80251", "-15.59808", "13.48251"),
    ("-15.59808", "13.48251", "-15.59808", "8.80251"),
    ("0", "14.80251", "9.07607", "14.80251"),
]
segments = [((F(a), F(b)), (F(c), F(d))) for a, b, c, d in raw]

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])

def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]

def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]

def on_segment(p, a, b):
    return (cross(sub(p, a), sub(b, a)) == 0
            and min(a[0], b[0]) <= p[0] <= max(a[0], b[0])
            and min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))

# Exact planarization: split at every endpoint and segment intersection.
points = {p for segment in segments for p in segment}
for a, b in segments:
    r = sub(b, a)
    for c, d in segments:
        s = sub(d, c)
        denominator = cross(r, s)
        if denominator:
            t = cross(sub(c, a), s) / denominator
            u = cross(sub(c, a), r) / denominator
            if 0 <= t <= 1 and 0 <= u <= 1:
                points.add((a[0] + t*r[0], a[1] + t*r[1]))

vertices = sorted(points)
index = {p: i for i, p in enumerate(vertices)}
edges = set()
for a, b in segments:
    split = sorted(p for p in points if on_segment(p, a, b))
    for p, q in zip(split, split[1:]):
        edges.add(tuple(sorted((index[p], index[q]))))

adj = defaultdict(set)
for u, v in edges:
    adj[u].add(v)
    adj[v].add(u)

# Exhaustively enumerate simple cycles. Minimum vertex and orientation
# constraints remove duplicates without omitting any polygonal boundary.
cycles = []
def extend(start, path, used):
    last = path[-1]
    for nxt in sorted(adj[last]):
        if nxt == start:
            if len(path) >= 3 and path[1] < path[-1]:
                cycles.append(tuple(path))
        elif nxt > start and nxt not in used:
            extend(start, path + [nxt], used | {nxt})

for start in range(len(vertices)):
    extend(start, [start], {start})

def simplify(poly):
    poly = list(poly)
    while True:
        keep = [
            p for i, p in enumerate(poly)
            if cross(sub(p, poly[i-1]),
                     sub(poly[(i+1) % len(poly)], p)) != 0
        ]
        if len(keep) == len(poly):
            return poly
        poly = keep
        if len(poly) < 3:
            return poly

def strictly_inside(p, poly):
    if any(on_segment(p, a, b)
           for a, b in zip(poly, poly[1:] + poly[:1])):
        return False
    inside = False
    for a, b in zip(poly, poly[1:] + poly[:1]):
        if (a[1] > p[1]) != (b[1] > p[1]):
            x = a[0] + (p[1]-a[1])*(b[0]-a[0])/(b[1]-a[1])
            if x > p[0]:
                inside = not inside
    return inside

# Relative squared tolerance accommodates five-decimal rounding.
TOL2 = F(1, 10**10)
def perpendicular(a, b):
    return dot(a, b)**2 <= TOL2 * dot(a, a) * dot(b, b)

def parallel(a, b):
    return cross(a, b)**2 <= TOL2 * dot(a, a) * dot(b, b)

def equal_length(a, b):
    x, y = dot(a, a), dot(b, b)
    return (x-y)**2 <= TOL2 * max(x, y)**2

def classify(poly):
    n = len(poly)
    e = [sub(poly[(i+1) % n], poly[i]) for i in range(n)]
    turns = [cross(e[i], e[(i+1) % n]) for i in range(n)]
    convex = all(t > 0 for t in turns) or all(t < 0 for t in turns)
    right = [perpendicular(e[i], e[(i+1) % n]) for i in range(n)]
    regular = (
        convex
        and all(equal_length(e[0], x) for x in e)
        and all(
            (dot(e[i], e[(i+1) % n]) -
             dot(e[0], e[1]))**2
            <= TOL2 * dot(e[0], e[0])**2
            for i in range(n)
        )
    )
    if n == 3:
        return 4 if any(right) else 3
    if n == 4:
        pairs = int(parallel(e[0], e[2])) + int(parallel(e[1], e[3]))
        if all(right):
            return 2 if all(equal_length(e[0], x) for x in e) else 1
        if convex and pairs == 2:
            return 5
        if convex and pairs == 1:
            return 6
    if n == 5:
        return 9 if regular else (7 if convex else 8)
    if n == 6 and regular:
        return 10
    return None

found = set()
strict_found = set()
witnesses = {}
for cycle in cycles:
    poly = simplify([vertices[i] for i in cycle])
    if len(poly) < 3:
        continue
    kind = classify(poly)
    if kind is None:
        continue
    found.add(kind)
    # Strong interpretation of "no diagonals": no stroke in the interior.
    interior_stroke = any(
        strictly_inside(
            ((vertices[u][0] + vertices[v][0])/2,
             (vertices[u][1] + vertices[v][1])/2),
            poly
        )
        for u, v in edges
    )
    if kind in (3, 4) or not interior_stroke:
        strict_found.add(kind)
        witnesses.setdefault(kind, poly)

options = {
    "A": {1, 8}, "B": set(), "C": {2}, "D": {5, 9},
    "E": {8}, "F": {1, 8, 5}, "G": {1, 8, 3, 4},
    "H": {1}, "I": {1, 5}, "J": {1, 8, 4, 9},
    "K": {1, 8, 6}, "L": {8, 3, 7}, "M": {2, 3},
    "N": {1, 7}, "O": {8, 2, 6, 10}, "P": {1, 8, 2},
}

print("Exact simple boundary cycles enumerated:", len(cycles))
print("Shape classes, allowing interior strokes:", sorted(found))
print("Shape classes, excluding interior strokes:", sorted(strict_found))
for kind, poly in sorted(witnesses.items()):
    print("Witness for class", kind, ":",
          [(str(x), str(y)) for x, y in poly])

print("Selected option I actually means:", sorted(options["I"]))
print("Submitted written list means:", [1, 3])
print("Matching listed options:",
      [letter for letter, content in options.items()
       if content == strict_found])

# Both interpretations are tested; neither the selected option nor its
# contradictory written description may be accepted without completeness.
if found == strict_found:
    expected = strict_found
    print("Computed complete shape set:", sorted(expected))
    if not any(content == expected for content in options.values()):
        print("No listed option exactly matches the computed shape set.")
    valid = options["I"] == expected and {1, 3} == expected
    print("CHECK PASS" if valid else "CHECK FAIL")
elif 3 in strict_found and 8 in strict_found:
    print("Class 3 disproves option I; class 8 disproves the written list.")
    print("CHECK FAIL")
else:
    print("UNSUPPORTED: interior-stroke interpretation affects the result.")
    print("CHECK UNKNOWN")
